public class Main {
    public static void main(String[] args) {
        boolean hasTicket = true;
        int age = 15;

        if (hasTicket) {
            if (age >= 18) {
                System.out.println("Enjoy the film.");
            } else {
                System.out.println("This film is for adults only.");
            }
        } else {
            System.out.println("Please buy a ticket first.");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int age = 14;
        double height = 1.20;

        if (age >= 12) {
            if (height >= 1.40) {
                System.out.println("You may ride.");
            } else {
                System.out.println("Old enough, but not tall enough.");
            }
        } else {
            System.out.println("Too young for this ride.");
        }
    }
}

