        boolean weekend = true;
        int price;

        if (age < 5) {
            price = 0;
        } else if (age < 13) {
            price = 120;
            if (weekend) {
                price += 50;
            }
        } else {
            price = 250;
            if (weekend) {
                price += 50;
            }
        }

        System.out.println("Price: " + price);
    }
}

